public static DataTable LoadPeriodDataTable(string permissionID, string permissionID2, string permissionID3)
{
    SimsObject.SIM_Branch obj = new SimsObject.SIM_Branch();
    return obj.GetDataTable("SIM_StudentCollectionPeriod_SearchForU",
                            "@PermissionID", permissionID,
                            "@PermissionID2", permissionID2,
                            "@PermissionID3", permissionID3,
                            "@LoginName", UserSession.Username);
}

public static void InitPeriodLookUpEdit(Control.UGridLookUpEdit lookup, string permissionID, string permissionID2, string permissionID3, bool insertEmptyRow)
{
    DataTable dtbPeriod = LoadPeriodDataTable(permissionID, permissionID2, permissionID3);
    if (insertEmptyRow)
        dtbPeriod.Rows.InsertAt(dtbPeriod.NewRow(), 0);

    lookup.InitData(dtbPeriod, "--Chọn--", "StudentCollectionPeriodID", "StudentCollectionPeriodName",
            "StudentCollectionPeriodID", "Mã đợt TS",
            "StudentCollectionPeriodName", "Tên đợt TS",
            "CourseName", "Khóa",
            "TrainingLevelName", "Bậc",
            "TrainingType", "Loại",
            "OfficeName", "Chi nhánh"
            );
}

